# Presentation clients all consume this same backend authoritative registry.
def registry_makes(self, query: str = "") -> list[str]:
    return self._request("GET", "/api/v1/vehicle-registry/makes", params={"q": query})

def registry_models(self, make: str, year: int | None = None) -> list[dict[str, Any]]:
    params: dict[str, Any] = {"make": make}
    if year is not None:
        params["year"] = year
    return self._request("GET", "/api/v1/vehicle-registry/models", params=params)

def registry_fitments(self, make: str, model: str, year: int | None = None) -> list[dict[str, Any]]:
    params: dict[str, Any] = {"make": make, "model": model}
    if year is not None:
        params["year"] = year
    return self._request("GET", "/api/v1/vehicle-registry/fitments", params=params)

def obd_protocol_hints(self, year: int, market: str = "unknown",
                       make: str = "", detected_elm: str | None = None) -> dict[str, Any]:
    return self._request("GET", "/api/v1/vehicle-registry/compatibility",
                         params={"year": year, "market": market, "make": make,
                                 **({"detected_elm": detected_elm} if detected_elm else {})})

def registry_photo(self, make: str, model: str, chassis: str = "") -> dict[str, Any]:
    return self._request("GET", "/api/v1/vehicle-registry/photo",
                         params={"make": make, "model": model, "chassis": chassis})

def get_session(self, session_id: str, language: str | None = None) -> dict[str, Any]:
    kwargs = {"params": {"language": language}} if language else {}
    return self._request("GET", f"/api/v1/sessions/{session_id}", **kwargs)

def analyze(self, session_id: str, language: str = "en") -> dict[str, Any]:
    normalized_language = language if language in {"en", "ru", "hy"} else "en"
    return self._request(
        "POST", f"/api/v1/analysis/{session_id}",
        params={"language": normalized_language},
        timeout=float(os.environ.get("AI_CAR_ANALYSIS_TIMEOUT_S", "300")),
    )

def decision_plan(self, session_id: str, language: str | None = None) -> dict[str, Any]:
    kwargs = {"params": {"language": language}} if language else {}
    return self._request("GET", f"/api/v1/decision/sessions/{session_id}/plan", **kwargs)

def active_probe(self, session_id: str, candidate_ids: list[str] | None = None) -> dict[str, Any]:
    payload: dict[str, Any] = {}
    if candidate_ids:
        payload["candidate_ids"] = candidate_ids
    return self._request("POST", f"/api/v1/network-discovery/sessions/{session_id}/active-probe", json=payload)

def ingest_reference(self, title: str, text: str) -> dict[str, Any]:
    return self._request("POST", "/api/v1/knowledge/ingest/text", json={
        "title": title, "text": text,
        "metadata": {"source": "user-reported-repair", "document_type": "repair_note"},
    })

def save_vehicle_profile(self, vehicle: dict, profile_id: str | None = None, name: str = ''):
    path = '/api/v1/vehicle-profiles' + (f'/{profile_id}' if profile_id else '')
    return self._request('PUT' if profile_id else 'POST', path, json={'name': name, 'vehicle': vehicle})

def download_report(self, session_id: str, format: str = 'pdf', language: str = 'en') -> bytes:
    response = self._send('GET', f'/api/v1/sessions/{session_id}/report', 60, {'params': {'format': format, 'language': language}})
    if not response.ok:
        raise ApiError(f'HTTP {response.status_code}: {response.text}')
    return response.content

def start(self) -> bool:
    if self._thread is not None:
        return True
    self._owned = self.process()
    if self._owned is None and not self.allow_initial_retry:
        logger.info("FastAPI recovery skipped: backend not owned by this launcher")
        return False
    # When a healthy unrelated API is present, never take it over.
    if self._owned is None and self.healthy():
        logger.info("FastAPI recovery skipped: external API already healthy")
        return False
    self._thread = threading.Thread(
        target=self._loop, name="AI-Car-FastAPI-recovery", daemon=True
    )
    self._thread.start()
    return True

def stop(self, *, join_timeout: float = 8.0) -> None:
    self.stop_event.set()
    thread = self._thread
    if thread is not None and thread is not threading.current_thread():
        thread.join(timeout=join_timeout)
        if thread.is_alive():
            logger.error("FastAPI recovery thread still active at shutdown")

def _loop(self) -> None:
    while not self.stop_event.wait(self.poll_seconds):
        self.check_once()

def check_once(self) -> str:
    """Run a single poll; deterministic tests can call this without threads."""
    if self.stop_event.is_set() or self.exhausted:
        return "stopped"
    owned = self.process()
    if owned is not None:
        self._owned = owned
        if owned.poll() is None:
            return "running"
    elif self._owned is None and not self.allow_initial_retry:
        return "external"

    # A healthy service on the same port may have started independently.
    if self.healthy():
        self.ever_healthy = True
        return "external"
    now = time.monotonic()
    if now < self._next_retry_at:
        return "backoff"
    while self._attempts and (now - self._attempts[0]) >= self.window_seconds:
        self._attempts.popleft()
    if len(self._attempts) >= self.max_restarts:
        self.exhausted = True
        logger.error(
            "FastAPI restart budget exhausted: %d attempts in %.0fs",
            self.max_restarts, self.window_seconds,
        )
        return "exhausted"
    if self.stop_event.is_set():
        return "stopped"
    self._attempts.append(now)
    self._next_retry_at = now + min(
        self.poll_seconds * 2 ** (len(self._attempts) - 1), 30.0
    )
    logger.warning(
        "FastAPI local process exited; recovery %d/%d",
        len(self._attempts), self.max_restarts,
    )
    try:
        recovered = self.restart()
    except Exception:
        logger.exception("FastAPI recovery attempt failed")
        return "failed"
    if self.stop_event.is_set():
        return "stopped"
    candidate = self.process()
    if candidate is not None:
        self._owned = candidate
    elif recovered is not None and hasattr(recovered, "poll"):
        self._owned = recovered
    is_healthy = self.healthy()
    self.ever_healthy = self.ever_healthy or is_healthy
    return "recovered" if is_healthy else "failed"

