def ensure_readable_size(self):
    if self.layout():
        self.layout().activate()
    minimum = self.minimumSizeHint().expandedTo(QSize(280, 360))
    self._readable_minimum = minimum
    self.setMinimumSize(minimum)
    if self._preferred_size:
        size = self._preferred_size.expandedTo(minimum)
        self.setFixedSize(size)
    self.updateGeometry()

def restore_size(self, size):
    try:
        width, height = (int(value) for value in size)
        if not (280 <= width <= 1600 and 360 <= height <= 1400):
            return
    except (TypeError, ValueError):
        return
    self._preferred_size = QSize(width, height)
    self.ensure_readable_size()

def showEvent(self, event):
    self.ensure_readable_size()
    super().showEvent(event)

def leaveEvent(self, event):
    if self._resize_origin is None:
        self.unsetCursor()
    super().leaveEvent(event)

"""Display conversion only. Acquisition and diagnostic evidence remain in SI."""
def convert(value, unit, us=False):
    if value is None or not us:
        return value, unit
    if unit == "km/h":
        return value / 1.609344, "mph"
    if unit in {"C", "°C"}:
        return value * 1.8 + 32, "°F"
    return value, unit

def display_records(records, us=False):
    result = []
    for record in records:
        value, unit = convert(record.get("numeric_value"), record.get("unit"), us)
        result.append(record | {"numeric_value": value, "unit": unit})
    return result

def fuel_values(value) -> list[str]:
    """Accept catalog strings and API lists, repairing old letter-split profiles."""
    if isinstance(value, str):
        values = re.split(r"[,+/]", value)
    elif isinstance(value, (list, tuple)):
        values = value
    else:
        return []
    values = [str(item).strip() for item in values if str(item).strip()]
    if len(values) > 1 and all(len(item) == 1 for item in values):
        word = "".join(values)
        if word.casefold() in {"diesel", "petrol", "gasoline", "lpg", "cng", "hybrid", "electric", "phev", "hev"}:
            return [word]
    return values

