def user_report_data(value):
    """Create an export snapshot without internal session identifiers."""
    if isinstance(value, dict):
        return {key: user_report_data(item) for key, item in value.items() if key != "session_id"}
    if isinstance(value, list):
        return [user_report_data(item) for item in value]
    return value

def endpoint(value):
    try:
        parsed=urlsplit(value)
        parsed.port
    except ValueError as error:
        raise argparse.ArgumentTypeError('Invalid backend URL') from error
    if parsed.scheme not in ('http','https') or not parsed.hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise argparse.ArgumentTypeError('Use a backend HTTP(S) URL without credentials/query/fragment')
    return value.rstrip('/')

