private class FakeDiagnosticApi : DiagnosticApi {
    override suspend fun decisionPlan(id:String,language:String):com.google.gson.JsonObject = error("Unused fixture action")
    override suspend fun aiProvider():com.google.gson.JsonObject = error("Unused fixture action")

override suspend fun vehicleRegistryModels(make: String, year: Int?): List<GlobalVehicleModelDto> =
    if (make == "Mercedes-Benz" && (year == null || year in 2002..2009)) listOf(
        GlobalVehicleModelDto(
            make = make, model = "E-Class", yearRanges = listOf(listOf(2002, 2009)),
            engineFamilies = listOf("M272"), commonFuels = listOf("petrol", "lpg"),
            source = "instrumentation-test"
        )
    ) else emptyList()

override suspend fun getSession(sessionId: String, language: String): DiagnosticSessionDto {
    require(sessionId == current.session_id)
    return current
}

override suspend fun updateVehicle(
    sessionId: String,
    vehicle: VehicleDto
): DiagnosticSessionDto = current.copy(vehicle = vehicle).also { current = it }

override suspend fun addSymptom(
    sessionId: String,
    request: SymptomRequest
): DiagnosticSessionDto = current.copy(
    symptoms = current.symptoms + SymptomDto(
        id = "symptom-${current.symptoms.size + 1}",
        raw_text = request.raw_text,
        normalized = request.normalized
    )
).also { current = it }

override suspend fun updateSymptom(
    sessionId: String,
    symptomId: String,
    request: SymptomRequest
): DiagnosticSessionDto = current.copy(
    symptoms = current.symptoms.map {
        if (it.id == symptomId) it.copy(raw_text = request.raw_text, normalized = request.normalized) else it
    }
).also { current = it }

override suspend fun deleteSymptom(
    sessionId: String,
    symptomId: String
): DiagnosticSessionDto = current.copy(
    symptoms = current.symptoms.filterNot { it.id == symptomId }
).also { current = it }

override suspend fun addDtc(
    sessionId: String,
    request: DtcRequest
): DiagnosticSessionDto = current.copy(
    dtcs = current.dtcs + DtcDto(
        id = "dtc-${current.dtcs.size + 1}",
        code = request.code,
        description = request.description
    )
).also { current = it }

override suspend fun updateDtc(
    sessionId: String,
    dtcId: String,
    request: DtcRequest
): DiagnosticSessionDto = current.copy(
    dtcs = current.dtcs.map {
        if (it.id == dtcId) it.copy(code = request.code, description = request.description) else it
    }
).also { current = it }

override suspend fun deleteDtc(
    sessionId: String,
    dtcId: String
): DiagnosticSessionDto = current.copy(
    dtcs = current.dtcs.filterNot { it.id == dtcId }
).also { current = it }

override suspend fun recordTestResult(
    sessionId: String,
    request: TestResultRequest,
    language: String
): DiagnosticSessionDto = current.copy(
    test_results = current.test_results + TestResultDto(
        test_id = request.test_id,
        result = request.result,
        measurements = request.measurements,
        notes = request.notes
    )
).also { current = it }

class LauncherReorderTest {
    @get:Rule val compose=createAndroidComposeRule<TestHostActivity>()

    @Test fun longPressDragPersistsAndTapStillOpensTheCorrectWorkflow() {
        val context=compose.activity
        val name="launcher-reorder-test"
        context.getSharedPreferences(name,Context.MODE_PRIVATE).edit().clear().commit()
        val store=LauncherOrderStore(context,name)
        var generation by mutableIntStateOf(0)
        var destination=-1
        compose.setContent {
            MaterialTheme(colorScheme=AutomotiveDarkColors) {
                Column(Modifier.verticalScroll(rememberScrollState())) {
                    key(generation) { DashboardSections(orderStore=store,navigate={destination=it}) }
                }
            }
        }
        val start=compose.onNodeWithText("Symptoms").fetchSemanticsNode().boundsInRoot.center
        val end=compose.onNodeWithText("Diagnostic").fetchSemanticsNode().boundsInRoot.center
        compose.onRoot().performTouchInput {
            down(start)
            advanceEventTime(700)
            moveTo(start)
            moveTo(end,500)
            up()
        }
        compose.runOnIdle {
            assertEquals(listOf(14,0),store.load(listOf(0,14,2,1,3,8,4,7,9,10,6,5,13,12)).take(2))
            assertEquals(-1,destination) // Dragging must not accidentally open a page.
            generation++
        }
        val diagnostic=compose.onNodeWithText("Diagnostic")
        val symptom=compose.onNodeWithText("Symptoms")
        assertTrue(diagnostic.fetchSemanticsNode().boundsInRoot.left < symptom.fetchSemanticsNode().boundsInRoot.left)
        diagnostic.performClick()
        compose.runOnIdle {assertEquals(14,destination)}
    }
}

