                assertEquals("410C1AF8", rpm.getOrThrow())

                val dtcs = client.readDtcs()
                assertTrue(dtcs.isSuccess)
                assertEquals("430102", dtcs.getOrThrow())

                assertTrue(server.commands.containsAll(listOf("ATZ", "ATE0", "ATL0", "ATS0", "ATSP0", "010C", "03")))
            } finally {
                client.close()
            }

