@dataclass(frozen=True)
class ChunkingConfig:
    target_chars: int = 1200
    overlap_chars: int = 180
    min_chars: int = 120

"""Heading-aware, paragraph-preserving chunker with overlap for retrieval continuity."""
def __init__(self, config: ChunkingConfig | None = None):
    self.config = config or ChunkingConfig()

def _blocks(self, text: str) -> list[str]:
    normalized = re.sub(r"\r\n?", "\n", text).strip()
    if not normalized:
        return []
    blocks = [b.strip() for b in re.split(r"\n\s*\n", normalized) if b.strip()]
    return blocks

def emit(items: list[tuple[int, int, str]], idx: int) -> KnowledgeChunk:
    content = "\n\n".join(x[2] for x in items).strip()
    meta = dict(base_metadata)
    pages = [p.page_number for p in parsed.pages if any(_overlaps_page(p, x[0], x[1], parsed.content) for x in items)]
    if pages:
        meta.update({"page_start": min(pages), "page_end": max(pages)})
    return KnowledgeChunk(
        stable_chunk_id(document_id, idx, content), document_id, idx, content, meta,
        min(pages) if pages else None, max(pages) if pages else None,
        items[0][0], items[-1][1]
    )

def _overlaps_page(page: ParsedPage, start: int, end: int, full_text: str) -> bool:
    # Page offsets are not explicitly stored by parsers; use ordered section matching as a safe approximation.
    # When there is one page it is exact; multi-page association is refined by the parser/pipeline in future versions.
    if len(full_text) == 0:
        return False
    return page.page_number == 1

@dataclass(frozen=True)
class RetrievalExample:
    query: str
    relevant_chunk_ids: tuple[str, ...]
    metadata_filters: dict
    source_case: str

class RetrievalDatasetBuilder:
    """Builds a simple, human-reviewable retrieval regression dataset from ingested chunks."""
    def from_results(self, results: Iterable[IngestionResult]) -> list[RetrievalExample]:
        out: list[RetrievalExample] = []
        for result in results:
            dtc_codes = set(re.findall(r"\bP\d{4}\b", " ".join(c.content for c in result.chunks), re.I))
            for code in sorted(dtc_codes):
                relevant = tuple(c.chunk_id for c in result.chunks if code.lower() in c.content.lower())
                if relevant:
                    filters = {k: v for k, v in result.document.metadata.to_dict().items() if k in {"manufacturer", "model", "year", "engine", "ecu"} and v is not None}
                    out.append(RetrievalExample(code, relevant, filters, result.document.document_id))
        return out

    @staticmethod
    def save(examples: Iterable[RetrievalExample], path: str | Path) -> None:
        payload = [e.__dict__ | {"relevant_chunk_ids": list(e.relevant_chunk_ids)} for e in examples]
        Path(path).write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")

