        headers = {"X-Image-Credit": quote(credit.get("creator", "")),
                   "X-Image-License": credit.get("license", ""),
                   "X-Image-Source": quote(credit.get("source_page", ""), safe=":/?=&%")}
    return FileResponse(path, headers=headers)

