def polling_plan(protocol_id="auto") -> dict:
    return {"schema_version": 1, "protocol_id": protocol_id,
            "initialization": initialization(protocol_id) + ["0100"],
            "initialization_timeout_ms": 35000,
            "discovery": ["0100", "ATDPN"],
            "commands": ["0100", "ATDPN"] + [p.command for p in PIDS],
            "read_only": True, "requires_prompt_terminated_responses": True}

def supported_polling_plan(responses: dict[str, str]) -> dict:
    """Select implemented live PIDs from observed Mode 01 PID 00 bitmaps.

    All current live channels are in the first page (01..20). Combine complete
    responses from multiple ECUs; never infer support from a model or a value.
    """
    frames = {key.upper().replace(" ", ""): value for key, value in responses.items()}
    payloads = ELM327Protocol.payloads("0100", frames.get("0100", "NO DATA"))
    masks = [int.from_bytes(p[2:], "big") for p in payloads if p[:2] == b"\x41\x00" and len(p) == 6]
    if not masks:
        raise OBDProtocolError("A complete Mode 01 PID 00 capability reply is required")
    mask = 0
    for value in masks:
        mask |= value
    supported = [pid for pid in range(1, 33) if mask & (1 << (32-pid))]
    commands = [pid.command for pid in PIDS if int(pid.command[2:], 16) in supported]
    return {"schema_version": 2, "initialization": [], "discovery": [],
            "commands": commands, "supported_pids": supported,
            "unsupported_commands": [pid.command for pid in PIDS if pid.command not in commands],
            "capabilities_observed": True, "read_only": True,
            "requires_prompt_terminated_responses": True}

def decode_snapshot(responses: dict[str, str]) -> dict:
    normalized = {key.upper().replace(" ", ""): value for key, value in responses.items()}
    values, errors = {}, {}
    for pid in PIDS:
        try:
            data = ELM327Protocol.parse_pid(int(pid.command[2:], 16), normalized.get(pid.command, "NO DATA"))
            if len(data) != pid.length:
                raise OBDProtocolError(f"Expected {pid.length} bytes; received {len(data)}")
            values[pid.key] = int.from_bytes(data, "big") * pid.scale + pid.offset
        except (ValueError, OBDProtocolError) as error:
            values[pid.key] = None
            errors[pid.command] = str(error)
    protocol = None
    if "ATDPN" in normalized:
        try:
            protocol = detected_protocol(normalized["ATDPN"])
        except ValueError as error:
            errors["ATDPN"] = str(error)
    return {"protocol": protocol, "values": values, "units": {p.key: p.unit for p in PIDS}, "errors": errors,
            "source": "native_transport_bridge", "hardware_verified": False}

def decode_packet(packet: bytes) -> dict:
    if not 4 <= len(packet) <= 21:
        raise ValueError('J1708 packets must contain 4..21 bytes including checksum')
    if sum(packet) & 255:
        raise ValueError('J1708 checksum mismatch')
    if packet[0] < 128:
        raise ValueError('Expected a J1587 application MID (128..255)')
    cursor, end, parameters = 1, len(packet)-1, []
    while cursor < end:
        pid = packet[cursor]
        cursor += 1
        extended = pid == 255
        if extended:
            if cursor >= end:
                raise ValueError('Missing extended PID')
            pid = packet[cursor]
            cursor += 1
        if pid >= 254:
            raise ValueError('Reserved/data-link escape PID needs a dedicated decoder')
        size = 1 if pid < 128 else 2 if pid < 192 else None
        if size is None:
            if cursor >= end:
                raise ValueError('Missing variable parameter length')
            size = packet[cursor]
            cursor += 1
        if size < 1 or cursor+size > end:
            raise ValueError('Truncated or empty J1587 parameter')
        parameters.append({'pid': pid+256 if extended else pid,
                           'raw_hex': packet[cursor:cursor+size].hex().upper()})
        cursor += size
    return {'mid': packet[0], 'parameters': parameters, 'checksum_valid': True,
            'source': 'native_j1708_capture', 'scope': 'Parameter framing only; no OEM scaling',
            'hardware_verified': False}

def decode_diagnostic_frame(arbitration_id: int, payload: bytes) -> dict:
    if not 0 <= arbitration_id <= 0x1FFFFFFF or len(payload) not in (6, 8):
        raise ValueError('Expected a 29-bit CAN identifier and a 6- or 8-byte single CAN frame')
    pf, ps = (arbitration_id >> 16) & 255, (arbitration_id >> 8) & 255
    pgn = (arbitration_id >> 8) & 0x3FFFF
    if pf < 240:
        pgn &= 0x3FF00
    if pgn not in (65226, 65227):
        raise ValueError('Only complete single-frame DM1/DM2 are supported; TP requires reassembly')
    records = []
    body = payload[2:]
    if len(body) not in (0, 4, 6) or (len(body) == 6 and body[4:] != b'\xFF\xFF'):
        raise ValueError('Truncated or invalid DM diagnostic record/padding')
    if len(body) >= 4 and body[:4] not in (b'\x00'*4, b'\xFF'*4):
        a, b, c, d = body[:4]
        cm = bool(d & 128)
        records.append({'spn': None if cm else a | (b << 8) | ((c & 224) << 11),
                        'fmi': c & 31, 'occurrence_count': d & 127,
                        'conversion_method': int(cm), 'raw': body[:4].hex().upper(),
                        'status': 'legacy_conversion_requires_profile' if cm else 'decoded'})
    return {'pgn': pgn, 'source_address': arbitration_id & 255,
            'destination_address': ps if pf < 240 else None,
            'kind': 'DM1' if pgn == 65226 else 'DM2',
            'lamp_status': payload[0], 'lamp_flash': payload[1], 'dtcs': records,
            'source': 'native_can_capture', 'hardware_verified': False}

def decode_bam_capture(frames: list[tuple[int, bytes]]) -> dict:
    """Reassemble one complete globally broadcast TP.BAM DM1/DM2 capture.

    Captures must already be time ordered. RTS/CTS and overlapping unrelated
    sessions are intentionally rejected instead of guessing packet ownership.
    """
    if not frames:
        raise ValueError('A complete BAM capture is required')
    identifier, announcement = frames[0]
    if not 0 <= identifier <= 0x1FFFFFFF or (identifier >> 8) & 0x3FFFF != 0xECFF:
        raise ValueError('First frame must be a global TP.CM BAM announcement')
    if len(announcement) != 8 or announcement[0] != 32 or announcement[4] != 255:
        raise ValueError('Invalid BAM announcement')
    size = int.from_bytes(announcement[1:3], 'little')
    count = announcement[3]
    pgn = int.from_bytes(announcement[5:8], 'little')
    if pgn not in (65226, 65227) or not 9 <= size <= 1785 or count != (size+6)//7 or len(frames) != count+1:
        raise ValueError('Incomplete/unsupported BAM diagnostic message')
    source = identifier & 255
    message = bytearray()
    for sequence, (identifier, payload) in enumerate(frames[1:], 1):
        if not 0 <= identifier <= 0x1FFFFFFF or (identifier >> 8) & 0x3FFFF != 0xEBFF or identifier & 255 != source:
            raise ValueError('BAM data source/destination mismatch')
        if len(payload) != 8 or payload[0] != sequence:
            raise ValueError('BAM data packet missing or out of sequence')
        message.extend(payload[1:])
    if any(value != 255 for value in message[size:]):
        raise ValueError('Invalid BAM trailing padding')
    message = message[:size]
    if (len(message)-2) % 4:
        raise ValueError('Truncated BAM diagnostic record')
    dtcs = []
    for offset in range(2, len(message), 4):
        decoded = decode_diagnostic_frame((pgn << 8) | source, bytes(message[:2]+message[offset:offset+4]))
        dtcs.extend(decoded['dtcs'])
    return {'pgn': pgn, 'source_address': source, 'kind': 'DM1' if pgn == 65226 else 'DM2',
            'lamp_status': message[0], 'lamp_flash': message[1], 'dtcs': dtcs,
            'transport': 'TP.BAM', 'source': 'native_can_capture', 'hardware_verified': False}

def initialization(protocol_id: str = "auto") -> list[str]:
    protocol = BY_ID.get(protocol_id)
    if protocol is None or protocol.elm_code is None or protocol.elm_code == "A":
        raise ValueError("Protocol is not supported by the generic ELM OBD-II reader")
    # Headers off, ISO-TP formatting on; the adapter owns link-layer framing.
    return ["ATZ", "ATE0", "ATL0", "ATS0", "ATH0", "ATCAF1", f"ATSP{protocol.elm_code}"]

def detected_protocol(raw: str) -> dict:
    value = raw.replace(">", "").strip().upper()
    automatic = value.startswith("A") and len(value) == 2
    code = value[1:] if automatic else value
    protocol = BY_ELM.get(code)
    if protocol is None or code == "0":
        raise ValueError("Unknown or unnegotiated ATDPN response")
    return asdict(protocol) | {"automatic": automatic, "observed": True}

def protocol_catalog() -> dict:
