def vin_from_response(raw: str) -> str | None:
    try:
        for payload in ELM327Protocol.payloads("0902", raw):
            if not payload.startswith(b"\x49\x02"):
                continue
            match = re.search(r"[A-HJ-NPR-Z0-9]{17}", payload[3:].decode("ascii", errors="ignore"))
            if match:
                return match.group()
    except ValueError:
        pass
    return None

def responding_modules(raw: str) -> list[dict]:
    modules = {}
    for line in re.split(r"[\r\n>]+", raw.upper()):
        match = re.match(r"^\s*([0-9A-F]{3}|[0-9A-F]{8})\s+", line)
        compact = "".join(line.split())
        address = match[1] if match else None
        if address is None and re.fullmatch(r"[0-9A-F]+", compact):
            if len(compact) > 10 and compact.startswith(("18DA", "18DB")):
                address = compact[:8]
            elif len(compact) >= 5 and len(compact) % 2:
                address = compact[:3]
        if address is None:
            continue
        try:
            payloads = ELM327Protocol.payloads("0100", line)
        except ValueError:
            continue
        if any(p.startswith(b"\x41\x00") and len(p) >= 6 for p in payloads):
            modules[address] = {"address": address, "name": "OBD ECU", "services": ["01-00"], "observed": True}
    if not modules:
        try:
            payloads = ELM327Protocol.payloads("0100", raw)
            if any(p.startswith(b"\x41\x00") and len(p) >= 6 for p in payloads):
                modules[None] = {"address": None, "name": "OBD ECU", "services": ["01-00"], "observed": True}
        except ValueError:
            pass
    return list(modules.values())

async def identify(responses: dict[str, str], *, simulated: bool = False) -> dict:
    vin = vin_from_response(responses.get("0902", ""))
    vehicle, lookup_status = None, "vin_unavailable"
    if vin and not simulated:
        try:
            vehicle = await asyncio.to_thread(nhtsa_decode_vin, vin)
            lookup_status = "identified" if vehicle.get("make") and vehicle.get("model") and vehicle.get("error_code") == "0" else "incomplete"
        except Exception:
            lookup_status = "lookup_unavailable"
    elif simulated:
        lookup_status = "simulated"
    modules = responding_modules(responses.get("0100", ""))
    protocol = None
    if modules and not simulated:
        from obd.protocols import detected_protocol
        try:
            protocol = detected_protocol(responses.get("ATDPN", ""))
        except ValueError:
            pass  # An adapter label alone is not proof of a negotiated ECU link.
    return {"vin": vin, "vehicle": vehicle, "identification_status": lookup_status,
            "modules": modules, "protocol": protocol, "simulated": simulated,
            "scope": "generic_obd_responders_only"}

async def collect(command) -> dict[str, str]:
    responses = {}
    try:
        for step in PLAN["commands"]:
            responses[step] = await command(step)
    finally:
        # Restore even when a bridge request times out or fails midway.
        for step in PLAN["restore"]:
            await command(step)
    return responses

class DoipClient:
    def __init__(self, host: str, *, source_address: int, target_address: int,
                 port: int = 13400, timeout: float = 5):
        if not host.strip() or not 1 <= port <= 65535:
            raise ValueError('A valid host and TCP port are required')
        if not all(1 <= address <= 65535 for address in (source_address, target_address)):
            raise ValueError('Logical addresses must be nonzero uint16 values')
        if not 0 < timeout <= 30:
            raise ValueError('Timeout must be within 0..30 seconds')
        self.host, self.port = host, port
        self.source, self.target, self.timeout = source_address, target_address, timeout
        self.reader = self.writer = None
        self.lock = asyncio.Lock()

    async def close(self):
        writer, self.writer = self.writer, None
        self.reader = None
        if writer:
            writer.close()
            try:
                await writer.wait_closed()
            except OSError:
                pass

    async def _send(self, kind: int, payload: bytes):
        self.writer.write(struct.pack('!BBHI', 2, 0xFD, kind, len(payload)) + payload)
        await self.writer.drain()

    async def _receive(self):
        header = await self.reader.readexactly(8)
        version, inverse, kind, size = struct.unpack('!BBHI', header)
        if version not in (2, 3) or version ^ inverse != 255:
            raise DoipError('Invalid DoIP version/header')
        if size > 65536:
            raise DoipError('DoIP payload exceeds 64 KiB limit')
        return kind, await self.reader.readexactly(size)

    async def _read_exchange(self, request: bytes):
        self.reader, self.writer = await asyncio.open_connection(self.host, self.port)
        await self._send(5, struct.pack('!HB4x', self.source, 0))
        kind, body = await self._receive()
        if kind != 6 or len(body) not in (9, 13) or int.from_bytes(body[:2], 'big') != self.source or body[4] != 0x10:
            raise DoipError('DoIP routing activation was not accepted')
        await self._send(0x8001, struct.pack('!HH', self.source, self.target) + request)
        for _ in range(32):
            kind, body = await self._receive()
            if kind == 7 and not body:
                await self._send(8, self.source.to_bytes(2, 'big'))
                continue
            if kind == 0x8002:
                if len(body) < 5 or body[:4] != struct.pack('!HH', self.target, self.source) or body[4] != 0:
                    raise DoipError('Invalid diagnostic acknowledgement')
                continue
            if kind != 0x8001 or len(body) < 5:
                raise DoipError(f'DoIP diagnostic request rejected (payload type 0x{kind:04X})')
            if body[:4] != struct.pack('!HH', self.target, self.source):
                raise DoipError('Diagnostic logical addresses do not match the requested ECU')
            response = body[4:]
            if response == bytes((0x7F, request[0], 0x78)):
                continue  # responsePending remains within the overall deadline.
            try:
                validate_positive(request, response)
            except ValueError as error:
                raise DoipError(str(error)) from error
            return response
        raise DoipError('DoIP response frame limit exceeded')

    async def read(self, request: bytes) -> bytes:
        validate_read_request(request)

