def ephemeral_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.bind(("127.0.0.1", 0))
        return int(sock.getsockname()[1])

def is_healthy(port: int) -> bool:
    try:
        with urlopen(f"http://127.0.0.1:{port}/health", timeout=1.0) as response:
            data = json.load(response)
            return (
                response.status == 200 and isinstance(data, dict)
                and data.get("status") == "ok"
                and data.get("service") == "diagnostic-api"
            )
    except (OSError, ValueError, TypeError):
        return False

def stop_child(process: subprocess.Popen, frozen: bool) -> None:
    """Stop only the child started by this probe, including Windows descendants.

    On Windows, backend_worker may have child processes holding SQLite open;
    terminating only the parent leaves diagnostic.sqlite locked.
    """
    if process.poll() is not None:
        return
    if sys.platform == "win32":
        # /PID is the exact Popen PID; /T only targets descendants of this PID.
        command = ["taskkill", "/PID", str(process.pid), "/T", "/F"]
        result = subprocess.run(
            command, capture_output=True, check=False, timeout=20,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        try:
            process.wait(timeout=12)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=8)
        if result.returncode != 0 and process.poll() is None:
            raise RuntimeError(
                f"Could not stop probe process tree PID={process.pid}: "
                + result.stderr.decode(errors="replace")[-400:]
            )
        return
    process.terminate()
    try:
        process.wait(timeout=10)
    except subprocess.TimeoutExpired:
        process.kill()
        process.wait(timeout=10)

def cleanup_temporary_database(folder: Path, *, attempts: int = 10) -> None:
    """Bounded Windows cleanup retry for delayed SQLite/AV handle release.

    Raises if deletion truly remains blocked. Caller writes a FAIL report with
    the preserved temporary folder path rather than losing startup evidence.
    """
    for attempt in range(attempts):
        try:
            shutil.rmtree(folder)
            return
        except FileNotFoundError:
            return
        except (PermissionError, OSError):
            if attempt == attempts - 1:
                raise
            time.sleep(min(0.3 + 0.2 * attempt, 1.0))

def inspect_png(path: Path) -> dict:
    from PIL import Image
    with Image.open(path) as image:
        if image.format != 'PNG' or image.mode != 'RGBA':
            raise ValueError(f'{path.name}: expected RGBA PNG')
        low, high = image.getchannel('A').getextrema()
        if low != 0 or high < 128 or min(image.size) < 200:
            raise ValueError(f'{path.name}: requires transparent background and visible vehicle')
        dimensions = list(image.size)
    return {'sha256': sha256(path.read_bytes()).hexdigest(), 'dimensions': dimensions}

def register(records: list[dict], root: Path = ROOT):
    path = root/'data/vehicle_reference.json'
    catalog = json.loads(path.read_text(encoding='utf-8'))
    cars = {row['id']: row for row in catalog['vehicles']}
    seen, staged = set(), []
    for record in records:
        key, source = record['id'], Path(record['path'])
        if key not in cars or key in seen:
            raise ValueError(f'Unknown or duplicated vehicle reference: {key}')
        seen.add(key)
        metadata = inspect_png(source)
        staged.append((key, source, metadata))
    if len({info['sha256'] for _, _, info in staged}) != len(staged):
        raise ValueError('Different vehicle generations must not reuse an identical illustration')
    manifest_path = root/'data/generated_vehicle_portraits.json'
    manifest = json.loads(manifest_path.read_text(encoding='utf-8')) if manifest_path.exists() else {'schema_version':1,'vehicles':{}}
    for key, source, metadata in staged:
        destination = root/'assets/vehicle_models'/f'{key}.png'
        destination.parent.mkdir(parents=True, exist_ok=True)
        if source.resolve() != destination.resolve():
            shutil.copyfile(source, destination)
        cars[key]['image'] = {'path': destination.relative_to(root).as_posix(), 'kind':'generated_illustration',
                             'attribution':'AI-generated vehicle illustration; not a manufacturer photograph'}
        manifest['vehicles'][key] = metadata | {'path':cars[key]['image']['path'],
            'kind':'generated_illustration','generator':'image_gen',
            'generated_asset_id':source.stem,'registered_at':datetime.now(timezone.utc).isoformat(),
            'notice':'Illustration only; vehicle geometry/trim is not manufacturer-certified'}
    manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    path.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    return len(staged)

def audit(root: Path = ROOT) -> dict:
    cars = json.loads((root/'data/vehicle_reference.json').read_text(encoding='utf-8'))['vehicles']
    missing, invalid, hashes = [], [], {}
    for car in cars:
        relative = car['image'].get('path')
        if not relative or not (root/relative).is_file():
            missing.append(car['id']); continue
        try:
            metadata = inspect_png(root/relative)
            hashes.setdefault(metadata['sha256'],[]).append(car['id'])
        except ValueError as error:
            invalid.append({'id':car['id'],'error':str(error)})
    duplicated = [ids for ids in hashes.values() if len(ids)>1]
    return {'generations':len(cars),'available':len(cars)-len(missing)-len(invalid),
            'missing':missing,'invalid':invalid,'duplicate_images':duplicated,
            'status':'FAIL' if missing or invalid or duplicated else 'PASS'}

def environment_values(*, include_defaults=True, environ=None):
    environ = os.environ if environ is None else environ
    paths = [PROJECT / 'config/environment.json'] if include_defaults else []
    local = (Path(sys.executable).resolve().parent / 'environment.local.json'
             if getattr(sys, 'frozen', False) else PROJECT / 'config/environment.local.json')
    paths.append(local)
    explicit = environ.get('AI_CAR_ENV_CONFIG')
    if explicit:
        path = Path(explicit).expanduser().resolve()
        if not path.is_file():
            raise ValueError(f'Environment configuration not found: {path}')
        paths.append(path)
    values = {}
    global_root = PROJECT if getattr(sys, "frozen", False) else PROJECT.parent
    if include_defaults and (global_root / 'config/global_config.json').is_file():
        # Importing configuration here is backend/setup-only; thin native clients
        # deliberately do not import this module.
        from backend.configuration.runtime import ConfigManager
        config = ConfigManager(root=global_root, environ=environ).snapshot
        values.update({'AI_CAR_BACKEND_PORT': str(config.services.backend_port),
                       'LOCAL_LLM_SERVER_CONTEXT': str(config.ai.context),
                       'DIAGNOSTIC_LLM_PROVIDER': config.ai.provider,
                       'LOCAL_LLM_TEMPERATURE': str(config.ai.temperature),
                       'LOCAL_LLM_MAX_TOKENS': str(config.ai.max_tokens),
                       'LOCAL_LLM_SERVER_TIMEOUT_S': str(config.ai.timeout_seconds)})
        if config.ai.endpoint != 'http://127.0.0.1:8000':
            values['LOCAL_LLM_SERVER_URL'] = config.ai.endpoint
        if config.ai.model_path != 'models':
            model_path = Path(config.ai.model_path).expanduser()
            values['LOCAL_LLM_MODEL_PATH'] = str(model_path if model_path.is_absolute() else PROJECT / model_path)
    for path in paths:
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding='utf-8'))
            if not isinstance(data, dict) or data.get('version') != 1 or not isinstance(data.get('environment'), dict):
                raise ValueError('Expected version 1 and an environment object')
            for name, value in data['environment'].items():
                if not re.fullmatch(r'[A-Z_][A-Z0-9_]*', name) or not isinstance(value, (str, int, float, bool)):
                    raise ValueError('Environment names must be uppercase and values must be strings, numbers or booleans')
                if path == PROJECT / 'config/environment.json' and name in values:
                    continue
                values[name] = ('1' if value else '0') if isinstance(value, bool) else str(value)
        except (OSError, ValueError) as error:
            raise ValueError(f'Invalid environment configuration: {path}: {error}') from error
    return values

def apply_environment(environ=None):
    """Set missing environment values; never overwrite an explicit process ENV."""
    environ = os.environ if environ is None else environ
    for name, value in environment_values(environ=environ).items():
        environ.setdefault(name, value)
    return environ

